#!/usr/bin/env python3
"""Compute deterministic numeric ground truth for CSX-320_Q2."""

from __future__ import annotations

import json
import re
from html import unescape
from pathlib import Path
from typing import Any


TASK_ID = "CSX-320_Q2"
EVENT_ID = "CSX-320"
TARGET_FAMILY = "mendenhall_glof_release_precip_radar_gate_consistency"

TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "data/event_reports/event_reports_004_Locked_event_anchor_Mendenhall_Glacier_outburst_flood.json",
    "data/remote_sensing/remote_sensing_003_Sentinel-1_GRD_VV_pre_post_change.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json",
]

GALLON_TO_CUBIC_METER = 0.003785411784
CFS_TO_CUBIC_METER_PER_SECOND = 0.028316846592


def load_json(rel_path: str) -> Any:
    with (PACKAGE_DIR / rel_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def load_html_text(rel_path: str) -> str:
    raw = (PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig", errors="replace")
    raw = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", raw)
    raw = re.sub(r"(?s)<[^>]+>", " ", raw)
    return re.sub(r"\s+", " ", unescape(raw)).strip().lower()


def round_float(value: float, digits: int = 4) -> float:
    return round(float(value), digits)


def first_number(pattern: str, text: str) -> float:
    match = re.search(pattern, text)
    if not match:
        raise ValueError(f"Missing report value for pattern: {pattern}")
    return float(match.group(1).replace(",", ""))


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Requested JSON form",
                "points": 4,
                "description": (
                    "Returns compact JSON with target_family, metrics, gates, answer, "
                    "and computed_consequence."
                ),
            },
            {
                "name": "Numeric anchors and formulas",
                "points": 5,
                "description": (
                    "Computes release volume in MCM, crest excess, flow floor in m3/s, "
                    "precipitation maximum, radar span, and coverage balance with correct units."
                ),
            },
            {
                "name": "Threshold gates",
                "points": 4,
                "description": (
                    "Applies the release, river, rainfall guardrail, and radar context gates "
                    "using the stated inequalities and reaches the correct answer label."
                ),
            },
            {
                "name": "Component reasoning",
                "points": 3,
                "description": (
                    "Shows how the conversion, difference, maximum, span, and balance calculations "
                    "were derived from event-package values rather than listing raw numbers only."
                ),
            },
            {
                "name": "Computed rejection",
                "points": 2,
                "description": (
                    "Rejects rainfall trigger dominance from the below-1 mm precipitation guardrail "
                    "while the release and river gates pass."
                ),
            },
            {
                "name": "Concise consequence",
                "points": 1,
                "description": "Keeps the computed consequence short and tied to the gates.",
            },
            {
                "name": "No overreach",
                "points": 1,
                "description": (
                    "Avoids treating radar context, annual surface change, population context, "
                    "or amenity counts as loss accounting."
                ),
            },
        ],
    }


def compute() -> dict[str, Any]:
    event = load_json(SOURCE_FILES[0])
    report_text = load_html_text(SOURCE_FILES[1])
    anchor = load_json(SOURCE_FILES[2])
    s1 = load_json(SOURCE_FILES[3])
    era5 = load_json(SOURCE_FILES[4])
    gpm = load_json(SOURCE_FILES[5])
    chirps = load_json(SOURCE_FILES[6])

    reported_crest_ft = first_number(r"crested at\s+([\d.]+)\s+feet", report_text)
    previous_record_crest_ft = first_number(r"previous record of\s+([\d.]+)\s+feet", report_text)
    streamflow_floor_cfs = first_number(
        r"streamflow exceeding\s+([\d,]+)\s+cubic feet per second", report_text
    )
    release_billion_gal = first_number(r"around\s+([\d.]+)\s+billion gallons", report_text)

    s1_counts = s1["counts"]
    s1_stats = s1["stats"]
    era5_stats = era5["stats"]
    gpm_stats = gpm["stats"]
    chirps_stats = chirps["stats"]

    daily_mean = chirps_stats["chirps_event_precip_mm_mean"]
    daily_mean_for_max = 0.0 if daily_mean is None else float(daily_mean)

    pre_count = int(s1_counts["pre_count"])
    post_count = int(s1_counts["post_count"])
    radar_span_db = (
        float(s1_stats["s1_vv_post_minus_pre_db_max"])
        - float(s1_stats["s1_vv_post_minus_pre_db_min"])
    )
    coverage_balance = min(pre_count, post_count) / max(pre_count, post_count)

    release_mcm = release_billion_gal * GALLON_TO_CUBIC_METER * 1000.0
    crest_excess_ft = reported_crest_ft - previous_record_crest_ft
    flow_floor_m3s = streamflow_floor_cfs * CFS_TO_CUBIC_METER_PER_SECOND
    precip_mean_max_mm = max(
        float(era5_stats["precipitation_sum_mm_mean"]),
        float(gpm_stats["gpm_event_precip_mm_mean"]),
        daily_mean_for_max,
    )

    metrics = {
        "release_mcm": round_float(release_mcm, 3),
        "crest_excess_ft": round_float(crest_excess_ft, 2),
        "flow_floor_m3s": round_float(flow_floor_m3s, 3),
        "precip_mean_max_mm": round_float(precip_mean_max_mm, 4),
        "radar_span_db": round_float(radar_span_db, 4),
        "coverage_balance": round_float(coverage_balance, 4),
    }

    gates = {
        "release_gate": metrics["release_mcm"] >= 50.0,
        "river_gate": metrics["crest_excess_ft"] >= 1.0 and metrics["flow_floor_m3s"] >= 900.0,
        "rainfall_guardrail": metrics["precip_mean_max_mm"] < 1.0 and daily_mean is None,
        "radar_context_gate": (
            pre_count >= 5
            and post_count >= 5
            and metrics["radar_span_db"] >= 20.0
            and metrics["coverage_balance"] >= 0.5
        ),
    }
    answer = (
        "mendenhall_glof_release_precip_radar_gate_pass"
        if all(gates.values())
        else "mendenhall_glof_release_precip_radar_gate_fail"
    )

    primary_gt = {
        "answer": answer,
        "target_family": TARGET_FAMILY,
        "metrics": metrics,
        "gates": gates,
        "computed_consequence": "rainfall_trigger_rejected_release_gate_passes",
        "tolerances": {
            "release_mcm": 0.001,
            "crest_excess_ft": 0.01,
            "flow_floor_m3s": 0.001,
            "precip_mean_max_mm": 0.0001,
            "radar_span_db": 0.0001,
            "coverage_balance": 0.0001,
        },
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "rubric": build_rubric(),
        "event": {
            "package_id": EVENT_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": anchor["temporal_window"]["start_date"],
        },
        "decision_rule": {
            "summary": (
                "All four gates must pass: release volume above 50 MCM, river crest and flow "
                "above thresholds, event-window precipitation below 1 mm with missing daily mean, "
                "and usable pre/post radar context."
            ),
            "formulas": {
                "release_mcm": "release_billion_gal * 3.785411784",
                "crest_excess_ft": "reported_crest_ft - previous_record_crest_ft",
                "flow_floor_m3s": "reported_streamflow_floor_cfs * 0.028316846592",
                "precip_mean_max_mm": "max(reanalysis_mean_mm, satellite_mean_mm, daily_mean_mm_or_zero)",
                "radar_span_db": "vv_change_max_db - vv_change_min_db",
                "coverage_balance": "min(pre_count, post_count) / max(pre_count, post_count)",
            },
            "thresholds": {
                "release_gate": "release_mcm >= 50",
                "river_gate": "crest_excess_ft >= 1.0 and flow_floor_m3s >= 900",
                "rainfall_guardrail": "precip_mean_max_mm < 1.0 and daily precipitation mean is missing",
                "radar_context_gate": "pre_count >= 5 and post_count >= 5 and radar_span_db >= 20 and coverage_balance >= 0.5",
            },
        },
        "key_values": {
            "report_anchors": {
                "release_billion_gal": release_billion_gal,
                "reported_crest_ft": reported_crest_ft,
                "previous_record_crest_ft": previous_record_crest_ft,
                "streamflow_floor_cfs": streamflow_floor_cfs,
            },
            "precipitation_means_mm": {
                "reanalysis": round_float(era5_stats["precipitation_sum_mm_mean"], 6),
                "satellite": round_float(gpm_stats["gpm_event_precip_mm_mean"], 6),
                "daily_is_missing": daily_mean is None,
            },
            "radar_inputs": {
                "pre_count": pre_count,
                "post_count": post_count,
                "min_db": round_float(s1_stats["s1_vv_post_minus_pre_db_min"], 4),
                "max_db": round_float(s1_stats["s1_vv_post_minus_pre_db_max"], 4),
            },
        },
        "numeric_tolerances": {
            "release_mcm": {"target": metrics["release_mcm"], "absolute_tolerance": 0.001},
            "crest_excess_ft": {"target": metrics["crest_excess_ft"], "absolute_tolerance": 0.01},
            "flow_floor_m3s": {"target": metrics["flow_floor_m3s"], "absolute_tolerance": 0.001},
            "precip_mean_max_mm": {
                "target": metrics["precip_mean_max_mm"],
                "absolute_tolerance": 0.0001,
            },
            "radar_span_db": {"target": metrics["radar_span_db"], "absolute_tolerance": 0.0001},
            "coverage_balance": {
                "target": metrics["coverage_balance"],
                "absolute_tolerance": 0.0001,
            },
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Deterministic local-file calculation with fixed formulas and numeric tolerances.",
        },
    }


def main() -> None:
    result = compute()
    OUTPUT_PATH.write_text(json.dumps(result, indent=2, sort_keys=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
